// The candidate list is generated, not discovered - which is the whole idea.
// Nobody keeps a list of the domains that impersonate them; that list is the
// thing you are trying to find. But the registrations are not creative: they are
// mechanical edits of a name, and mechanical edits can be enumerated.
//
// single-item input: Settings emits one row and this runs once per sweep.
const cfg = $('Settings').first().json;

function host(s) {
  return String(s || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[\/?#].*$/, '');
}

const home = host(cfg.your_domain);
if (!home || home.indexOf('.') < 0) {
  throw new Error('Set your_domain in Settings to the domain you actually own, for example acme.com');
}

// Split on the FIRST dot, not the last. A brand on acme.co.uk has "co.uk" as its
// suffix, and splitting on the last dot would generate acme.co-style names that
// have nothing to do with the real one.
const dot = home.indexOf('.');
const stem = home.slice(0, dot);
const tld = home.slice(dot + 1);

const brand = String(cfg.brand_name || stem).trim().toLowerCase().replace(/[^a-z0-9]/g, '') || stem;

// Domains you already own and never want to hear about. Kept as bare hosts so a
// full URL, a www prefix or a trailing slash all normalise to the same thing.
const owned = {};
owned[home] = true;
String(cfg.domains_you_own || '')
  .split(/[|,\s]+/)
  .map(host)
  .filter(Boolean)
  .forEach(function (d) { owned[d] = true; });

// --- the classes ----------------------------------------------------------
// Each returns bare stems. The TLD is attached afterwards, because two classes
// want a different one.

const KEYS = {
  a: 'qsz', b: 'vgn', c: 'xdv', d: 'sfce', e: 'wrd', f: 'dgrv', g: 'fhtb',
  h: 'gjyn', i: 'uok', j: 'hkun', k: 'jlim', l: 'kop', m: 'njk', n: 'bmhj',
  o: 'ipl', p: 'ol', q: 'wa', r: 'etdf', s: 'adwx', t: 'rygf', u: 'yijh',
  v: 'cbfg', w: 'qes', x: 'zcsd', y: 'tuhg', z: 'asx',
  '0': 'o9', '1': 'l2', '2': '13', '3': '24', '4': '35', '5': '46',
  '6': '57', '7': '68', '8': '79', '9': '80',
};

const HOMOGLYPH = [
  ['l', '1'], ['i', '1'], ['i', 'l'], ['o', '0'], ['e', '3'], ['a', '4'],
  ['s', '5'], ['b', '6'], ['g', '9'], ['m', 'rn'], ['w', 'vv'], ['n', 'm'],
  ['cl', 'd'], ['rn', 'm'],
];

function omissions(s) {
  const out = [];
  for (let i = 0; i < s.length; i++) out.push(s.slice(0, i) + s.slice(i + 1));
  return out;
}

function doubles(s) {
  const out = [];
  for (let i = 0; i < s.length; i++) out.push(s.slice(0, i + 1) + s.charAt(i) + s.slice(i + 1));
  return out;
}

function swaps(s) {
  const out = [];
  for (let i = 0; i < s.length - 1; i++) {
    out.push(s.slice(0, i) + s.charAt(i + 1) + s.charAt(i) + s.slice(i + 2));
  }
  return out;
}

function neighbours(s) {
  const out = [];
  for (let i = 0; i < s.length; i++) {
    const near = KEYS[s.charAt(i)] || '';
    for (let k = 0; k < near.length; k++) {
      out.push(s.slice(0, i) + near.charAt(k) + s.slice(i + 1));
    }
  }
  return out;
}

function homoglyphs(s) {
  const out = [];
  for (let p = 0; p < HOMOGLYPH.length; p++) {
    const from = HOMOGLYPH[p][0];
    const to = HOMOGLYPH[p][1];
    // Replace one occurrence at a time rather than all of them. "google" with
    // every o swapped is g00gle, which is real, but so is go0gle - and only
    // replacing one at a time produces both.
    let at = s.indexOf(from);
    while (at >= 0) {
      out.push(s.slice(0, at) + to + s.slice(at + from.length));
      at = s.indexOf(from, at + 1);
    }
  }
  return out;
}

function hyphens(s) {
  const out = [];
  for (let i = 1; i < s.length; i++) out.push(s.slice(0, i) + '-' + s.slice(i));
  return out;
}

const WORDS = String(cfg.impersonation_words || '')
  .split(/[|,\s]+/)
  .map(function (w) { return w.trim().toLowerCase().replace(/[^a-z0-9]/g, ''); })
  .filter(Boolean);

function keyworded(s) {
  const out = [];
  for (let i = 0; i < WORDS.length; i++) {
    out.push(s + '-' + WORDS[i]);
    out.push(s + WORDS[i]);
    out.push(WORDS[i] + '-' + s);
  }
  return out;
}

const TLDS = String(cfg.other_tlds || '')
  .split(/[|,\s.]+/)
  .map(function (t) { return t.trim().toLowerCase(); })
  .filter(Boolean);

// --- assemble -------------------------------------------------------------
// Ordered classes, because the cap below takes from them in turn. The order is
// the priority order: a one-character typo on your own TLD is a likelier
// registration than your brand on .site.
const classes = [
  ['homoglyph', homoglyphs(brand).map(function (s) { return s + '.' + tld; })],
  ['omission', omissions(brand).map(function (s) { return s + '.' + tld; })],
  ['transposition', swaps(brand).map(function (s) { return s + '.' + tld; })],
  ['tld', TLDS.map(function (t) { return brand + '.' + t; })],
  ['keyword', keyworded(brand).map(function (s) { return s + '.' + tld; })],
  ['doubling', doubles(brand).map(function (s) { return s + '.' + tld; })],
  ['neighbour', neighbours(brand).map(function (s) { return s + '.' + tld; })],
  ['hyphen', hyphens(brand).map(function (s) { return s + '.' + tld; })],
];

// Round-robin, not a slice and not a sample. A slice would spend the entire
// budget on whichever class happens to be first; a random sample would hand a
// different set of domains to every run, and "this changed since yesterday"
// would silently come to mean "this was not in yesterday's sample". The diff is
// the product, so the sweep has to be the same sweep every day.
const cap = Math.max(4, Math.min(300, Number(cfg.max_candidates) || 60));
const seen = {};
const picked = [];
let depth = 0;
let guard = 0;
while (picked.length < cap && guard < 4000) {
  let addedThisPass = false;
  for (let c = 0; c < classes.length && picked.length < cap; c++) {
    const list = classes[c][1];
    if (depth >= list.length) continue;
    addedThisPass = true;
    const d = list[depth];
    guard++;
    if (!d || seen[d] || owned[d]) continue;
    seen[d] = true;
    picked.push({ domain: d, source: classes[c][0] });
  }
  if (!addedThisPass) break;
  depth++;
}

// One item, not many. The SERP node downstream must fire once per sweep, and a
// node fed twenty items fires twenty times.
return [{ json: {
  brand: brand,
  home: home,
  candidates: picked,
  generated: picked.length,
  // -site: keeps your own pages out of the ten results Google returns, so the
  // whole page is spent on everybody else.
  search_query: '"' + brand + '" (login OR "official site" OR "sign in" OR download) -site:' + home,
}}];

// The second lane, and the honest one about its own hit rate.
//
// Measured 2026-08-27: this exact query against a well-known brand returned ten
// organic results and not one was an impersonation - Reddit, YouTube, the Play
// Store, two help centres, a partner portal. That is the normal outcome. The
// lane is here for the registration no permutation could have produced, and it
// earns its place perhaps once a month.
//
// single-item input: one SERP request, one parsed response.
// The SERP zone is called with `format: json`, and that returns the whole HTTP
// envelope - { status_code, headers, body } - with the parsed SERP nested in
// `body` as a STRING. Reading `organic` off the top level finds nothing and
// reports a clean sweep, which is the wrong direction to fail in. Measured live
// on 2026-08-27: the node received a 23 KB envelope, `payload.organic` was
// undefined, and a query that returned ten real results in curl reported zero.
function unwrapSerp(x) {
  let p = x;
  if (p && p.body != null) p = p.body;
  if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = {}; }
  } else if (p && typeof p.data === 'string') {
    try { p = JSON.parse(p.data); } catch (e) { p = {}; }
  } else if (p && p.data && typeof p.data === 'object') {
    p = p.data;
  }
  return p || {};
}

const body = unwrapSerp($input.first().json);

// Bright Data answers validation errors and rate limits with HTTP 200 and an
// error body, and neverError means nothing throws. Say so rather than reporting
// a quiet zero.
if (body && body.error) {
  throw new Error('Bright Data SERP returned an error: ' + JSON.stringify(body.error).slice(0, 300));
}

const plan = $('Generate The Lookalikes').first().json;

// Anything that hosts other people's content will match a brand name and is
// never itself the impersonator. Without this the report is nine platforms and
// one finding, every single day.
const PLATFORMS = [
  'google', 'youtube', 'reddit', 'facebook', 'instagram', 'twitter', 'x.com',
  'linkedin', 'tiktok', 'pinterest', 'medium', 'substack', 'github', 'gitlab',
  'stackoverflow', 'quora', 'wikipedia', 'apple.com', 'apps.apple.com',
  'play.google.com', 'microsoft.com', 'amazon', 'ebay', 'etsy', 'shopify.com',
  'wordpress.com', 'blogspot', 'notion.so', 'trustpilot', 'glassdoor', 'indeed',
  'crunchbase', 'g2.com', 'capterra', 'producthunt', 'yelp', 'bbb.org',
  'archive.org', 'cloudflare.com', 'godaddy', 'namecheap', 'sedo',
];

function host(u) {
  return String(u || '')
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[\/?#].*$/, '');
}

function registrable(h) {
  const parts = h.split('.');
  return parts.length > 2 ? parts.slice(-3).join('.') : h;
}

const organic = (body && body.organic) || [];
const already = {};
plan.candidates.forEach(function (c) { already[c.domain] = true; });

const out = [];
for (let i = 0; i < organic.length; i++) {
  const h = host(organic[i].link);
  if (!h) continue;
  if (h === plan.home || h.slice(-(plan.home.length + 1)) === '.' + plan.home) continue;
  let skip = false;
  for (let p = 0; p < PLATFORMS.length; p++) {
    if (h.indexOf(PLATFORMS[p]) >= 0) { skip = true; break; }
  }
  if (skip) continue;
  // Only a host that carries the brand name is worth fetching. A page about you
  // on someone else's domain is coverage, not impersonation.
  if (h.indexOf(plan.brand) < 0) continue;
  const d = registrable(h);
  if (already[d]) continue;
  already[d] = true;
  out.push({ domain: d, source: 'search' });
}

// One item, matching the other lane, so the Merge below appends two objects
// rather than one object and eleven.
return [{ json: { candidates: out, found: out.length } }];

// Join the two lanes to what was recorded last sweep.
//
// Read the history from $input and the candidates by name. The Data Table sits
// between the Merge and this node, so $input here is the stored rows - the
// candidates have to be pulled from the node that built them.
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.domain; });

// alwaysOutputData is on upstream, so an empty table on the first run arrives as
// one item with no domain field. Filtering on `r.domain` above is what turns
// that into an empty history instead of a row keyed on undefined.
const history = {};
rows.forEach(function (r) { history[r.domain] = r; });

const lanes = $('Combine Both Lanes').all().map(function (i) { return i.json; });
const plan = $('Generate The Lookalikes').first().json;

const seen = {};
// The first row is your own site, fetched through the same Unlocker as every
// candidate so the comparison downstream is like for like. It costs one extra
// request per sweep and it is what stops a domain you own and redirect from
// being reported as an impersonation of yourself - measured on 2026-08-27,
// where a `-login` variant of a real brand returned 28,531 bytes of that
// brand's own homepage and scored as impersonation with high confidence.
const out = [{ json: {
  domain: plan.home,
  source: 'reference',
  url: 'https://' + plan.home,
  brand: plan.brand,
  home: plan.home,
  is_reference: true,
  prev_state: 'reference',
  prev_verdict: 'reference',
}}];
seen[plan.home] = true;
lanes.forEach(function (lane) {
  (lane.candidates || []).forEach(function (c) {
    if (!c || !c.domain || seen[c.domain]) return;
    seen[c.domain] = true;
    const prev = history[c.domain] || {};
    out.push({ json: {
      domain: c.domain,
      source: c.source,
      url: 'https://' + c.domain,
      brand: plan.brand,
      home: plan.home,
      prev_state: String(prev.state || 'unchecked'),
      prev_verdict: String(prev.verdict || 'unchecked'),
    }});
  });
});

if (out.length < 2) {
  throw new Error('No candidates were generated. Check brand_name and your_domain in Settings.');
}
return out;

// Three states, read off the response size, because that is what the Unlocker
// actually gives you.
//
// Measured 2026-08-27 through web_unlocker1 with data_format markdown:
//   stripe.com          24,905 bytes   live
//   stripe.co              384 bytes   parked  ("Available for sale!", NamePros)
//   str1pe.com               0 bytes   unregistered
//   stripe-billing.com       0 bytes   unregistered
//   stripee.com              0 bytes   unregistered
// Zero is a fetch that returned nothing, not a page that disagrees - and it is
// the single cheapest way to ask "did anyone take this name" without a WHOIS
// key. The middle band is real and has to be its own state: somebody is holding
// the domain, which is worth a row, but nothing is being served and it must not
// page anyone at 07:00.
const items = $input.all();
const cands = $('Build The Candidate List').all();
const out = [];

const PARK = /(domain (is )?(for sale|parked)|available for sale|buy this domain|this domain (is|may be) for sale|inquire about this domain|parked (free )?courtesy|sedoparking|afternic|namepros|dan\.com|hugedomains)/i;

function words(s) {
  return String(s || '').toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/).filter(Boolean);
}

// Overlap of the first 200 words, as a set. Word-set rather than string equality
// because a real homepage carries a rotating banner, a cookie line and a build
// hash, so two fetches of the same site minutes apart are never byte-identical
// but always share their vocabulary.
function overlap(a, b) {
  if (!a.length || !b.length) return 0;
  const seen = {};
  a.slice(0, 200).forEach(function (w) { seen[w] = true; });
  const bw = b.slice(0, 200);
  const counted = {};
  let hits = 0;
  for (let i = 0; i < bw.length; i++) {
    if (seen[bw[i]] && !counted[bw[i]]) { counted[bw[i]] = true; hits++; }
  }
  const union = Object.keys(seen).length + Object.keys(counted).length - hits;
  return union ? hits / union : 0;
}

function textOf(raw) {
  return typeof raw === 'string' ? raw : String(raw.data || raw.body || '');
}

// Row 0 is your own site, fetched through this same node. It is the reference,
// never a candidate, so it is read here and then dropped.
const homeWords = words(textOf(items[0].json));

for (let i = 1; i < items.length; i++) {
  const cand = cands[i].json;
  const md = textOf(items[i].json);
  const bytes = md.length;

  let state = 'live';
  if (bytes === 0) state = 'unregistered';
  else if (bytes < 1200 || PARK.test(md)) state = 'parked';

  // The false positive that costs the most credibility, measured live on
  // 2026-08-27: a `-login` variant of a real brand returned 28,531 bytes of that
  // brand's own homepage, and the model called it impersonation with high
  // confidence. It was almost certainly a domain the brand owns and redirects.
  // A page serving your own words is either you or a mirror of you, and a page
  // fetch cannot tell those two apart - so it gets its own bucket instead of a
  // guess, and it never reaches the model.
  const similarity = state === 'live' ? overlap(homeWords, words(md)) : 0;
  const mirrors = similarity >= 0.75;

  // What the model gets to read. A real page is far too long to send whole and
  // the giveaways are all near the top: the title, the headline, the sign-in
  // prompt. Four thousand characters covers those on every page tested.
  const sample = md.replace(/\s+/g, ' ').trim().slice(0, 4000);

  out.push({ json: {
    domain: cand.domain,
    url: cand.url,
    source: cand.source,
    brand: cand.brand,
    home: cand.home,
    prev_state: cand.prev_state,
    prev_verdict: cand.prev_verdict,
    state: state,
    bytes: bytes,
    mirrors_home: mirrors,
    home_overlap: Math.round(similarity * 100) / 100,
    page_text: sample,
  }});
}
return out;

// A Code node, not a Filter, for one reason: a Filter that matches nothing ends
// its branch, and everything below it - the judgement, the diff, the Data Table
// write - would silently never run on the morning when every candidate is dead.
// That is the good morning, and it is exactly the morning you would stop hearing
// about.
//
// So it always emits at least one item. The sentinel costs one cheap model call
// on a quiet day and is dropped again downstream.
// A site serving your own words is excluded here rather than judged. The model
// has no way to tell your redirect from a mirror of you, and asking it produces
// a confident answer to a question the evidence does not settle.
const live = $input.all().filter(function (i) {
  return i.json.state === 'live' && !i.json.mirrors_home;
});
if (live.length) return live;

return [{ json: {
  sentinel: true,
  domain: '',
  url: '',
  brand: '',
  page_text: 'No candidate domain resolved to a live site in this sweep.',
}}];

