// Normalise before anything counts it.
//
// The Information Extractor nests its result under `output`, and reading
// $json.verdict instead of $json.output.verdict returns undefined on every item
// - which produces an all-clear report on a run where every node is green.
//
// Enums come back off-list often enough to plan for: three earlier templates on
// this account saw "in-office" for a remote_policy field and "very negative" for
// a sentiment one. Anything unrecognised becomes inconclusive rather than a new
// category nobody defined.
const VERDICTS = { impersonating: 1, affiliated: 1, unrelated: 1, inconclusive: 1 };
const WANTS = { credentials: 1, payment: 1, download: 1, traffic: 1, nothing: 1 };
const CONF = { high: 1, medium: 1, low: 1 };

const out = [];
$input.all().forEach(function (item, idx) {
  const src = $('Only The Live Ones').all()[idx];
  if (!src || src.json.sentinel) return;

  const j = (item.json && item.json.output) || item.json || {};
  let verdict = String(j.verdict || '').toLowerCase().trim();
  if (!VERDICTS[verdict]) verdict = 'inconclusive';

  let wants = String(j.what_it_wants || '').toLowerCase().trim();
  if (!WANTS[wants]) wants = 'nothing';

  let conf = String(j.confidence || '').toLowerCase().trim();
  if (!CONF[conf]) conf = 'low';

  // The guard that keeps a plausible answer from becoming a takedown. The model
  // is told to copy its evidence verbatim from the page; if the quote is not
  // actually on the page it read, the verdict is not evidence-backed and gets
  // demoted rather than reported.
  const quote = String(j.evidence || '').replace(/\s+/g, ' ').trim();
  const page = String(src.json.page_text || '').replace(/\s+/g, ' ');
  const grounded = quote.length > 12 && page.indexOf(quote.slice(0, 60)) >= 0;
  if (verdict === 'impersonating' && !grounded) verdict = 'inconclusive';

  out.push({ json: {
    domain: src.json.domain,
    verdict: verdict,
    confidence: conf,
    what_it_wants: wants,
    evidence: grounded ? quote.slice(0, 400) : '',
  }});
});

// Never zero items - the diff below reads this by name and an empty branch here
// would take the Data Table write with it.
if (!out.length) return [{ json: { domain: '', verdict: 'none', skip: true } }];
return out;

// Rebuild the full sweep, judged rows and unjudged alike.
//
// The judgement lane only carries the live sites, so the dead and parked ones
// are read back by name from the classifier. Doing it here rather than with a
// Merge keeps the two lanes from having to arrive in step - and a Merge fed one
// empty branch would drop the other one's items on a quiet day.
const judged = {};
$input.all().forEach(function (i) {
  if (i.json && i.json.domain && !i.json.skip) judged[i.json.domain] = i.json;
});

const now = new Date().toISOString().slice(0, 19).replace('T', ' ');
const all = $('Classify What Came Back').all().map(function (i) { return i.json; });

const out = all.map(function (r) {
  const j = judged[r.domain] || {};
  // A domain nobody registered, a parking page and a site serving your own copy
  // are all facts about the domain rather than opinions about a page, so none of
  // them reach the model and none of them get a model verdict.
  let verdict = r.state;
  if (r.mirrors_home) verdict = 'mirrors_you';
  else if (r.state === 'live') verdict = String(j.verdict || 'inconclusive');
  const changed = verdict !== r.prev_verdict;
  // The first sweep marks everything as changed by definition, which would post
  // sixty lines to Slack on day one. A domain seen for the first time is only
  // worth reporting if it is actually a finding.
  const first = r.prev_verdict === 'unchecked';
  return { json: {
    domain: r.domain,
    source: r.source,
    state: r.state,
    bytes: r.bytes,
    home_overlap: r.home_overlap,
    verdict: verdict,
    prev_verdict: r.prev_verdict,
    confidence: String(j.confidence || ''),
    what_it_wants: String(j.what_it_wants || ''),
    evidence: String(j.evidence || ''),
    changed: changed,
    first_seen: first,
    report: verdict === 'impersonating' && (changed || first),
    flag_mirror: verdict === 'mirrors_you' && (changed || first),
    checked_at: now,
  }};
});

return out;

// One message for the sweep, not one per domain.
const rows = $input.all().map(function (i) { return i.json; });

const findings = rows.filter(function (r) { return r.report; });
const mirrors = rows.filter(function (r) { return r.flag_mirror; });
const parked = rows.filter(function (r) { return r.state === 'parked'; });
const live = rows.filter(function (r) { return r.state === 'live'; });
// A domain that used to impersonate and now does not is worth a line too - it
// usually means somebody took it down, and that is the end of a story you
// started.
// Mirrors are excluded because they already have their own line above. Without
// this a domain that moves from impersonating to mirrors_you is announced twice
// in the same message, which reads like two separate events.
const cleared = rows.filter(function (r) {
  return r.prev_verdict === 'impersonating' && r.verdict !== 'impersonating' && !r.flag_mirror;
});

const WANT = {
  credentials: 'asks for a login',
  payment: 'asks for payment',
  download: 'offers a download',
  traffic: 'just takes the traffic',
  nothing: 'no obvious ask',
};

const lines = [];
lines.push('*Lookalike sweep* - ' + rows.length + ' domains checked, ' +
  live.length + ' live, ' + parked.length + ' parked, ' +
  (rows.length - live.length - parked.length) + ' unregistered.');

if (findings.length) {
  lines.push('');
  lines.push(':rotating_light: *' + findings.length + ' impersonating ' +
    (findings.length === 1 ? 'domain' : 'domains') + '*');
  findings.slice(0, 12).forEach(function (f) {
    lines.push('• `' + f.domain + '` (' + f.source + ', ' + f.confidence +
      ' confidence) - ' + (WANT[f.what_it_wants] || f.what_it_wants));
    if (f.evidence) lines.push('    > ' + f.evidence.slice(0, 220));
  });
}

if (mirrors.length) {
  lines.push('');
  lines.push(':twisted_rightwards_arrows: *Serving your own pages* - either a domain you own and redirect, or a mirror of you. The registration record is the only thing that tells them apart.');
  mirrors.slice(0, 8).forEach(function (m) {
    lines.push('• `' + m.domain + '` (' + m.source + ', ' +
      Math.round(m.home_overlap * 100) + '% of your own wording)');
  });
}

if (cleared.length) {
  lines.push('');
  lines.push(':white_check_mark: *No longer impersonating:* ' +
    cleared.map(function (c) { return '`' + c.domain + '`'; }).join(', '));
}

lines.push('');
lines.push('_Registration and intent are not visible from a page fetch. Confirm before you file anything._');

return [{ json: {
  message: lines.join('\n'),
  has_findings: findings.length > 0 || mirrors.length > 0 || cleared.length > 0,
  finding_count: findings.length,
}}];
